import{_ as t,o,c as r,ah as i}from"./chunks/framework.Bja9t6Wf.js";const d=JSON.parse(`{"title":"Research: The Eurofighter Affair (Austria's Billion-Dollar Grave)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/eurofighter.md","filePath":"en/recherche/eurofighter.md"}`),a={name:"en/recherche/eurofighter.md"};function s(n,e,h,l,f,c){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="research-the-eurofighter-affair-austria-s-billion-dollar-grave" tabindex="-1">Research: The Eurofighter Affair (Austria&#39;s Billion-Dollar Grave) <a class="header-anchor" href="#research-the-eurofighter-affair-austria-s-billion-dollar-grave" aria-label="Permalink to &quot;Research: The Eurofighter Affair (Austria&#39;s Billion-Dollar Grave)&quot;">​</a></h1><p><strong>A masterpiece of political aviation – and the opaque procurement processes behind it.</strong></p><p>The Eurofighter procurement is the largest, most expensive, and most controversial defense deal in the history of the Second Republic of Austria. For our mockumentary, it serves as a prime example of the &quot;pointillism of capital&quot; in the defense sector.</p><hr><h2 id="the-deal" tabindex="-1">The Deal <a class="header-anchor" href="#the-deal" aria-label="Permalink to &quot;The Deal&quot;">​</a></h2><p>In 2002, the ÖVP-FPÖ government under Chancellor Wolfgang Schüssel decided to purchase 24 Eurofighter Typhoon fighter jets. After the 2002 floods, the order was reduced to 18, and later (under Minister Darabos) to 15 jets.</p><h3 id="key-points-of-criticism" tabindex="-1">Key Points of Criticism: <a class="header-anchor" href="#key-points-of-criticism" aria-label="Permalink to &quot;Key Points of Criticism:&quot;">​</a></h3><ul><li><strong>Corruption Allegations:</strong> For years, investigations have been ongoing into suspicious &quot;offset transactions&quot; and alleged bribe payments amounting to millions.</li><li><strong>The Eurofighter Committee of Inquiry:</strong> Multiple parliamentary committees have attempted to shed light on the networks of lobbyists and politicians.</li><li><strong>Heidi Horten&#39;s Mention:</strong> Although not directly involved in the Eurofighter deal, the mention of her name in the Ibiza video (&quot;Horten is paying&quot;) brought the general system of party donations back into the spotlight of the Eurofighter investigations.</li></ul><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>The Eurofighter affair represents the &quot;Old Style&quot; of large-scale procurement – bulky, expensive, and legally difficult to grasp. We use it as a contrast to the &quot;New Style&quot; of donation splitting. While the Eurofighter was a massive, visible block of steel, the Horten donations were a shimmering mosaic of small tranches.</p><ul><li><strong>Satirical Motif:</strong> We show the Eurofighters as expensive toys of an elite that has lost its sense of proportionality – much like the oversized yachts and art collections.</li></ul><hr><p><em>Sources: Reports of the various Eurofighter Committees of Inquiry, investigative reporting by Profil and Der Standard.</em></p>',14)])])}const g=t(a,[["render",s]]);export{d as __pageData,g as default};
